#!/usr/bin/env bash
# Verifier driver for step 10 (quiche 0.20.0).
#
# Generated by misc/quic-http3-stack-multiversion/tools/gen-step.py from the
# shared frame plus this step's group list. Edit the frame or the step part and
# regenerate; do not edit one copy in isolation. After Phase 3 opens on a step
# the generated copy becomes authoritative and the reviser edits it directly —
# `tools/carryover-check.sh` is what keeps the fifteen copies honest after that.
set -u
source /tests/helpers.sh

# --- verifier/step binding check -------------------------------------------
# Must be the first thing that runs: /etc/harbor-step-id names the image, the
# literal below names this tests/ tree, and a disagreement means the build
# context was served from another step's cache entry.
require_step 10
# --- end binding check ------------------------------------------------------

# ---------------------------------------------------------------------------
# 0. Crash path.
#
# Under `multi_step_reward_strategy = "mean"` a verifier that exits without a
# reward.json costs the whole trial the steps after it, so every exit from here
# on writes a complete scorecard and exits 0. `fail_everything` is the
# scorecard for a driver that died before it could measure anything.
#
# It reports `gate: 0` with an empty `gate_failures`, and that pairing is the
# signal: a gate of zero with no group named is the driver failing, not a
# candidate regressing. Anything that vetoes a real step names the group and
# quotes what it saw.
# ---------------------------------------------------------------------------
reported=0

fail_everything() {
    local reason="$1"
    printf '{"step":%s,"reward":0.000000,"gate":0,"score":0.000000,"gate_failures":[],"candidate_build":0,"harness_build":0,"fixture_ok":0,"budget_exhausted":0,"crate_dir":"unresolved","build_note":"%s","gate_groups":{},"scored_groups":{}}\n' \
        "${step_num:-0}" "$reason" > /logs/verifier/reward_details.json
    printf '{"reward":0.000000}\n' > /logs/verifier/reward.json
}

on_exit() {
    local status=$?
    if [ "${reported:-0}" -ne 1 ]; then
        fail_everything "the verifier driver exited with status $status before it reported: nothing was measured, so this is an unattributable verifier failure rather than a capability result"
    fi
    exit 0
}
trap on_exit EXIT

step_num=10
step_tag=0.20.0
log_dir=/tmp/quiche-verifier-10
harness=/tmp/quiche-harness-10
assets=/tests/assets
mkdir -p "$log_dir"

# ---------------------------------------------------------------------------
# 1. Fixture integrity.
#
# The verifier-owned corpus — the RFC 9001 Appendix A vectors, the frame and
# QPACK vector files, and the e2e drivers — is a prerequisite for the groups
# that consume it, never a score point of its own. A broken corpus fails those
# groups; it must not short-circuit the independent ones or erase earned
# credit.
# ---------------------------------------------------------------------------
expected_assets_sha=5c34a000e481fefcf8a9a2ef14dd18e9ff12f05e4c20a3328f317a361738a4d8
expected_asset_files=34

actual_assets_sha=$(cd "$assets" && find . -type f -print0 | LC_ALL=C sort -z \
    | xargs -0 sha256sum | sha256sum | awk '{print $1}')
actual_asset_files=$(find "$assets" -type f | wc -l)

fixture_ok=1
[ "$actual_assets_sha" = "$expected_assets_sha" ] || fixture_ok=0
[ "$actual_asset_files" -eq "$expected_asset_files" ] || fixture_ok=0

# ---------------------------------------------------------------------------
# 2. Locating the candidate's transport crate.
#
# The library lives at the workspace root until milestone 6 and under
# `quiche/` from milestone 6 onward. Both layouts are accepted everywhere and
# the layout itself is scored by its own group at the step that introduces it,
# so a candidate that has not yet moved the tree loses that one group rather
# than every group in the step. TEST_INTERFACE.md states this probe.
# ---------------------------------------------------------------------------
crate_dir=unresolved
for cand in /app/quiche /app; do
    if [ -f "$cand/Cargo.toml" ] && grep -Eq '^[[:space:]]*name[[:space:]]*=[[:space:]]*"quiche"' "$cand/Cargo.toml"; then
        crate_dir=$cand
        break
    fi
done

workspace_root=/app
[ -f /app/Cargo.toml ] || workspace_root=$crate_dir

# ---------------------------------------------------------------------------
# 2. (continued) Which BoringSSL this tree was written against.
#
# The image pins the library this milestone's release pins, and the environment
# names it. At most steps that is the only copy and this loop does nothing.
#
# Where the QUIC callback struct changed shape across a step boundary, the
# image carries the previous release's pin as well. `SSL_QUIC_METHOD` is a
# struct of function pointers passed to `SSL_set_quic_method`: releases up to
# 0.1.0 declare four members, beginning `set_encryption_secrets`; from 0.3.0
# they declare five, beginning `set_read_secret` and `set_write_secret`. A tree
# of the older shape handed to a library of the newer one links cleanly -- the
# symbol exists and takes a pointer -- and then reads one member past the end
# of the struct, calling the wrong function for every callback. Nothing errors.
# The handshake simply never emits a ClientHello, and the step's inherited
# regression groups fail for a linkage reason wearing behaviour's clothes.
#
# So the shape is read out of the candidate's own `src/tls.rs` and the matching
# library selected. The test is deliberately two-sided -- the old name present
# AND the new names absent -- so a tree part-way through the conversion, or one
# that merely mentions the old name in a comment, keeps this release's library.
# The shape is read out of *live code*: `//` comments are stripped before the
# two greps run, so a migration note naming the old field cannot flip the pick.
# A candidate who does the work is unaffected: the environment already names
# the right one, and this loop never fires. It cannot manufacture a pass for
# the scored groups either; those ask for behaviour this milestone introduced,
# which no older library supplies.
#
# `.cargo/config.toml` in the workdir sets the same variable through cargo's
# `[env]` table, which without `force = true` yields to a variable already set
# in the environment -- so exporting here is enough, and the file stays honest
# about the default.
# ---------------------------------------------------------------------------
if [ -n "${QUICHE_BSSL_PATH:-}" ] && [ -f "$crate_dir/src/tls.rs" ] &&
    sed 's,//.*,,' "$crate_dir/src/tls.rs" | grep -q 'set_encryption_secrets' &&
    ! sed 's,//.*,,' "$crate_dir/src/tls.rs" | grep -q 'set_read_secret'; then
    for alt in /opt/bssl/*; do
        [ -d "$alt" ] || continue
        [ "$alt" = "$QUICHE_BSSL_PATH" ] && continue
        QUICHE_BSSL_PATH=$alt
        export QUICHE_BSSL_PATH
        break
    done
fi

# ---------------------------------------------------------------------------
# 2a. The time budget, and why these numbers.
#
# `task.toml` gives this step `[steps.verifier] timeout_sec = 3600`. If the
# verifier is killed by that timeout it never writes reward.json and the run is
# unattributable rather than a zero, so the work inside must provably fit
# whatever the candidate does:
#
#   verify the pinned asset corpus                               <   5 s
#   CANDIDATE_BUILD_TIMEOUT  one `cargo build` of /app, cold    <= 1000 s
#   EXAMPLES_BUILD_TIMEOUT   the best-effort examples pass      <=  240 s
#   APPS_BUILD_TIMEOUT       the best-effort app-package pass   <=  240 s
#   HARNESS_BUILD_TIMEOUT    one `cargo test --no-run` of the
#                            verifier-owned harness crate       <=  800 s
#   CASE_BUDGET_TOTAL        every gate check and every scored
#                            group together                     <= 1200 s
#   write the two JSON files                                     <   5 s
#                                                    worst case   3490 s
#
# PER_CASE_MAX is far above any real case and far below the aggregate: one
# hanging case costs its own group and at most 120 s of the shared pool, so a
# step with many hanging cases degrades group by group instead of taking the
# run down. BoringSSL and the whole dependency graph are prebuilt into the
# image, so the candidate build is the candidate's own code and nothing else.
CANDIDATE_BUILD_TIMEOUT=1000
EXAMPLES_BUILD_TIMEOUT=240
APPS_BUILD_TIMEOUT=240
HARNESS_BUILD_TIMEOUT=800
CASE_BUDGET_TOTAL=1200
PER_CASE_MAX=120

# ---------------------------------------------------------------------------
# 3. Build the candidate workspace once, before anything is scored.
#
# Recorded separately from the groups: every group runs against this build, so
# one compile error would otherwise be reported as N unrelated capability gaps.
# ---------------------------------------------------------------------------
candidate_build=0
if [ "$crate_dir" != unresolved ]; then
    # Default targets only -- libraries and binaries. Deliberately not
    # `--all-targets`: that would also compile the candidate's own test and
    # bench targets, so a broken test of theirs would fail the build and be
    # reported as every capability missing at once. Their tests are not what
    # this verifier measures.
    (cd "$workspace_root" && timeout "$CANDIDATE_BUILD_TIMEOUT" \
        cargo build --offline -j 4) \
        >"$log_dir/candidate-build.log" 2>&1 && candidate_build=1
    # The client and server lived under examples/ before they became their own
    # package. Best-effort and never fatal: at releases where they are bins the
    # build above already produced them, and at releases where there are no
    # examples this is a no-op.
    if [ "$candidate_build" -eq 1 ]; then
        (cd "$workspace_root" && timeout "$EXAMPLES_BUILD_TIMEOUT" \
            cargo build --offline --examples -j 4) \
            >"$log_dir/candidate-examples.log" 2>&1 || true
    fi
    # Later they moved out of examples/ and into a package of their own --
    # `tools/apps` first, then `apps`. Where that package is a workspace member
    # the build above already covered it; where it exists but the root manifest
    # has no [workspace] section, cargo never descends into it, so the tree
    # ships the client and server sources and produces neither binary. Building
    # the package where it sits covers that window, and builds more of the
    # candidate rather than asking less of it.
    #
    # Best-effort, like the examples pass, and bounded as one pass rather than
    # one per path: at a release whose lockfile predates this package's own
    # dependencies it cannot resolve offline at all, which is a property of the
    # pinned corpus and not a candidate defect. Building a non-member package
    # makes cargo write a lockfile beside its manifest; no group reads one.
    if [ "$candidate_build" -eq 1 ]; then
        apps_deadline=$(( $(date +%s) + APPS_BUILD_TIMEOUT ))
        for app in tools/apps apps; do
            [ -f "$workspace_root/$app/Cargo.toml" ] || continue
            left=$(( apps_deadline - $(date +%s) ))
            [ "$left" -gt 0 ] || break
            (cd "$workspace_root/$app" && timeout "$left" \
                cargo build --offline -j 4) \
                >"$log_dir/candidate-app-$(printf '%s' "$app" | tr / -).log" \
                2>&1 || true
        done
    fi
fi

# The client and server binaries are the process boundary most groups use.
# The harness resolves them itself, by name, from the CANDIDATE_* variables
# below -- the names are the step's own interface section's, and the harness
# applies them name-major over the directories it searches. The driver does
# not pre-resolve a binary and does not prefer any spelling of its own: a
# second resolution rule written here could only ever disagree with that one.
target_dir=${CARGO_TARGET_DIR:-$workspace_root/target}

export QUICHE_CRATE_DIR="$crate_dir"
export QUICHE_WORKSPACE="$workspace_root"
export QUICHE_ASSETS="$assets"
export QUICHE_LOGDIR="$log_dir"

# What `verifier::testkit` reads. The harness has to find the candidate's
# binaries, and in this image they are not under /app/target: CARGO_TARGET_DIR
# is set image-wide so the prewarmed dependency graph is reused, which moves
# every artefact to /opt/cargo-target. Telling the harness where the tree and
# the artefacts actually are keeps that an image detail instead of something
# each of the fifteen steps' test files has to know.
export CANDIDATE_ROOT="$workspace_root"
export CANDIDATE_TARGET_DIR="$target_dir"
# Scratch directories are deliberately never cleaned up: when a case fails, the
# document root, the captured stdout and the server log it left behind are the
# evidence. Rooting them in the log directory keeps them beside the case log.
export VERIFIER_SCRATCH="$log_dir/scratch"
mkdir -p "$VERIFIER_SCRATCH"

# ---------------------------------------------------------------------------
# 4. The throw-away harness crate.
#
# It lives outside /app so that a candidate cannot make its own acceptance pass
# by editing the cases, and so that nothing the harness needs is ever added to
# the candidate's manifest. It declares exactly one dependency — a path
# dependency on the candidate's own transport crate — so a harness build
# failure is always about the candidate's public surface and never about a
# registry.
# ---------------------------------------------------------------------------
# Does the candidate's manifest declare a Cargo feature by this name?
#
# Either an explicit entry under [features], or an optional dependency of the
# same name, which Cargo turns into a feature implicitly.
# Does the candidate's manifest declare `$2` as a feature?
#
# Three spellings are legal Cargo for "this crate can be built with a `qlog`
# feature", and all three have to be recognised or a correct manifest is read
# as not declaring it, the feature is dropped from the harness's own edge, and
# every `cap` group fails to link for a reason that is not the candidate's:
#
#   [features]
#   qlog = []
#
#   [dependencies]
#   qlog = { version = "..", optional = true }
#
#   [dependencies.qlog]
#   optional = true
#
# The third puts the name in the section header and never in field 1, which is
# why the spelling is tracked as well as the key.
declares_feature() {
    awk -v want="$2" '
        /^[[:space:]]*\[/ {
            sec = $1
            gsub(/^\[|\]$/, "", sec)
            section = sec
            dep_table = (sec == "dependencies." want || sec == "dev-dependencies." want \
                         || sec == "build-dependencies." want)
            next
        }
        $1 == want && $2 == "=" && section == "features" { found = 1 }
        $1 == want && $2 == "=" && section ~ /dependencies$/ \
            && $0 ~ /optional[ \t]*=[ \t]*true/ { found = 1 }
        dep_table && $1 == "optional" && $2 == "=" && $3 == "true" { found = 1 }
        END { exit found ? 0 : 1 }
    ' "$1"
}

prepare_harness() {
    rm -rf -- "$harness"
    mkdir -p "$(dirname "$harness")"
    # The whole tree, not a hand-listed subset: the harness is a two-member
    # workspace (the verifier crate and `support/`, the independent QUIC
    # implementation) and it carries its own `assets/` — the TLS keypair and
    # the RFC vectors the cases load through `testkit::asset`. Copying file
    # patterns instead would silently drop whichever of those a future step
    # starts using, and the resulting build failure would be charged to the
    # candidate.
    cp -a -- "$assets/harness" "$harness"
    # The only edit: the candidate's crate path, which is not known until the
    # probe above has run. Resolved here rather than in the checked-in manifest
    # so the manifest stays identical in all fifteen steps.
    sed -i "s#@@CRATE_DIR@@#$crate_dir#g" "$harness/Cargo.toml"
    # Optional feature requests, resolved against the candidate's own manifest.
    #
    # Cargo validates every feature reference while it resolves the graph,
    # before it compiles anything, so asking a milestone for a feature it does
    # not declare fails the whole harness build -- including the gate targets,
    # which never touch the feature. Names marked `# optional-feature:` in the
    # harness manifest are therefore kept only when the candidate declares
    # them. The scored case that needs one then fails to compile by itself,
    # which is the right answer for a candidate that has not built it.
    for feat in $(sed -n 's/^#[[:space:]]*optional-feature:[[:space:]]*//p' \
        "$harness/Cargo.toml"); do
        if declares_feature "$crate_dir/Cargo.toml" "$feat"; then
            printf 'kept optional feature %s\n' "$feat" \
                >>"$log_dir/harness-features.log"
        else
            sed -i "s/\"$feat\"[[:space:]]*,[[:space:]]*//; s/,[[:space:]]*\"$feat\"//; s/\"$feat\"//" \
                "$harness/Cargo.toml"
            printf 'dropped optional feature %s: the candidate does not declare it\n' \
                "$feat" >>"$log_dir/harness-features.log"
        fi
    done
    # No lockfile, on purpose. One authored against the reference tree would
    # pin the candidate's own dependency versions, turning a legitimate
    # difference in their manifest into a harness build failure that reads as
    # their fault. The registry cache is prewarmed, so resolving offline here
    # costs nothing.
    rm -f -- "$harness/Cargo.lock"
}

harness_build=0
if [ "$candidate_build" -eq 1 ]; then
    prepare_harness
    (cd "$harness" && timeout "$HARNESS_BUILD_TIMEOUT" \
        cargo test --offline --no-run -j 4) \
        >"$log_dir/harness-build.log" 2>&1 && harness_build=1
fi

# The case pool starts here, so a slow build cannot eat it.
case_deadline=$(( $(date +%s) + CASE_BUDGET_TOTAL ))
budget_exhausted=0

# remaining_budget -> seconds left in the shared pool, or 0
remaining_budget() {
    local r=$(( case_deadline - $(date +%s) ))
    [ "$r" -lt 0 ] && r=0
    printf '%s\n' "$r"
}

# run_case <log-name> <test-target> <test-fn>
#
# Each case is bounded by the smaller of PER_CASE_MAX and what is left of
# CASE_BUDGET_TOTAL, so the cases can never overrun that total however many of
# them hang. A killed case exits non-zero and scores that one group 0, which is
# the same outcome as any other failure; once the pool is spent the remaining
# groups are failed without running and the reason is recorded, which is still a
# zero rather than a lost run.
run_case() {
    local name="$1" target="$2" fn="$3" remaining limit status
    remaining=$(remaining_budget)
    if [ "$remaining" -le 5 ]; then
        budget_exhausted=1
        printf 'the aggregate case budget of %s s was exhausted before this case ran\n' \
            "$CASE_BUDGET_TOTAL" >"$log_dir/$name.log"
        return 1
    fi
    if [ ! -d "$harness" ]; then
        # The harness crate is assembled only after a candidate transport crate
        # has been located. When it was not, every case here would fail on `cd`
        # with a shell error in its log, which reads as a broken driver rather
        # than as a result. The group does fail -- but for a definite reason,
        # and the reason belongs on the group that fired it.
        {
            printf 'the harness crate was never assembled, so this case could not run.\n'
            printf 'assembly is skipped when no candidate transport crate was located\n'
            printf '(crate_dir=%s): there was nothing for the harness to link against.\n' "$crate_dir"
            printf 'This group fails for that reason, not for anything it asserts.\n'
        } >"$log_dir/$name.log"
        return 1
    fi
    limit=$PER_CASE_MAX
    [ "$remaining" -lt "$limit" ] && limit=$remaining
    (cd "$harness" && timeout "$limit" \
        cargo test --offline --test "$target" "$fn" -- --exact --nocapture) \
        >"$log_dir/$name.log" 2>&1
    status=$?
    [ "$status" -eq 0 ] || return "$status"
    # Every invocation asserts an exact executed count: a name filter that
    # matches nothing still exits 0, and would otherwise be scored as a pass.
    grep -q 'test result: ok\. 1 passed; 0 failed; 0 ignored' "$log_dir/$name.log"
}

# ---------------------------------------------------------------------------
# 5. The gate.
#
# Proof of life plus inherited regression: that the candidate builds, that its
# two binaries still complete a handshake and a transfer over real UDP, and
# that one deterministic end-to-end path per earlier milestone still works.
#
# Gate groups earn nothing. They only veto: if any one of them fails the step
# is worth zero however much of this step's own capability landed. That is
# deliberate. A candidate that implements this release by breaking the last one
# has not advanced the ladder, and an additive score would pay it for the parts
# that still happen to work.
#
# The corollary governs what is allowed in here. A gate case that can fail for
# a reason other than the candidate's code -- a wall clock, a host's CPU count,
# an unordered iteration read as ordered -- is not weak coverage, it is a step
# that randomly scores zero for everyone including the reference. Every case
# below is deterministic, and the ones that were not were deleted rather than
# demoted; NOTES.md lists them and why.
#
# Behaviour this step deliberately changes is likewise not in here. A migration
# left in the gate is a step whose own reference implementation fails it.
# ---------------------------------------------------------------------------
gate_ok=1
gate_log=$log_dir/gate.txt
: > "$gate_log"

gate_check() {
    local name="$1"; shift
    if "$@"; then
        printf 'PASS %s\n' "$name" >> "$gate_log"
    else
        printf 'FAIL %s\n' "$name" >> "$gate_log"
        gate_ok=0
    fi
}

candidate_builds() { [ "$candidate_build" -eq 1 ]; }

# Every other gate group is a case or a driver and leaves `$log_dir/<name>.log`
# behind, which is where the scorer reads the reason a veto fired. This one is
# a flag set back in section 3, so give it the log the flag came from.
if [ -f "$log_dir/candidate-build.log" ]; then
    cp -f "$log_dir/candidate-build.log" "$log_dir/candidate-workspace-builds.log"
else
    # Section 3 runs cargo only when a quiche crate was located. When it was
    # not, no candidate-build.log exists, and copying it silently left this
    # group with no log at all -- which the scorer reports as "the case did not
    # run". That reads like a harness that failed to fire, when in fact the
    # group failed for a definite reason. A veto must carry its reason on the
    # group that fired it, so write it here rather than leave the scorer to
    # guess. The step-level build_note says the same thing; this puts it where
    # a reader looks first.
    {
        printf 'no cargo build was attempted: crate_dir=%s\n' "$crate_dir"
        printf 'no Cargo.toml declaring the package name `quiche` was found at\n'
        printf '/app or /app/quiche, so there was no transport crate to build.\n'
        printf 'This group fails by definition: proof-of-life cannot pass when\n'
        printf 'the candidate shipped no library to prove alive.\n'
    } > "$log_dir/candidate-workspace-builds.log"
fi
gate_check candidate-workspace-builds candidate_builds
# T1: The candidate's own client and server complete a half-megabyte transfer over UDP loopback with `--perform-migration`, the client exits zero and the bytes are identical. Carried because this step renames the connection-ID methods the migration path is built out of, and a rename applied to the library but not to `apps/` breaks exactly this. Step 08's group also required the client to be *observed* holding two UDP sockets at once, which is what distinguishes a migration from a reconnection. That leg is not carried into the gate. It needs a sampler -- the harness polls `/proc/<pid>/fd` against `/proc/net/udp` roughly every 20 ms -- and whether a poll lands inside the overlap is a question about the host's scheduler. Step 08's `cap-probe-and-migrate` still asks it, where a miss costs that group's weight and vetoes nothing.
gate_check reg-08-probe-and-migrate run_case reg-08-probe-and-migrate reg reg_08_probe_and_migrate
# T2: The verifier owns a UDP socket, completes a handshake as the peer, flips the key-phase bit, and requires the candidate to derive the next generation of application keys with the `"quic ku"` label while reusing its header- protection key, to answer under the new generation with its own phase bit flipped, and to reject a second update before the first is acknowledged with `Err(Error::KeyUpdate)`. Carried because it is the step immediately before this one and its machinery sits underneath every short-header packet the new C entry points send.
gate_check reg-09-key-update run_case reg-09-key-update reg reg_09_key_update
# T3: With `enable_dgram(true, 10, 10)` on both sides, a 256-byte datagram is echoed back byte-for-byte, it never appears as stream data, and both queues drain to `Err(Error::Done)`. Carried because this step adds C predicates over those same two queues and because the transport DATAGRAM API is the one thing step 09 deleted *around* without touching.
gate_check reg-04-datagram-roundtrip run_case reg-04-datagram-roundtrip reg reg_04_datagram_roundtrip
# T1: The stack works at all: the candidate's `quiche-server` starts, the candidate's `quiche-client` completes a handshake against it over UDP loopback and retrieves a small file, and the client exits zero. If this fails, every other T1 observation at this step is noise.
gate_check gate-endtoend run_case gate-endtoend gate gate_endtoend

# ---------------------------------------------------------------------------
# 6. The scored groups.
#
# This step's new capability, plus peripheral breadth. Each group is one
# coherent behaviour and is invoked separately, so a failure localises, and
# every group runs even after another has failed: a partial implementation
# keeps exactly the credit it earned.
#
# Weights live in `/tests/groups.json` and sum to one across the groups here,
# so this step's score is in [0, 1] and is the weighted fraction of its own new
# behaviour that works. Nothing in this section knows a weight -- it records
# PASS or FAIL per group and the scorer prices it -- so a revision that edits a
# group here cannot silently desync the driver from the manifest.
# ---------------------------------------------------------------------------
group_log=$log_dir/groups.txt
: > "$group_log"

score_if() {
    local name="$1"; shift
    if "$@"; then
        printf 'PASS %s\n' "$name" >> "$group_log"
    else
        printf 'FAIL %s\n' "$name" >> "$group_log"
    fi
}

# T3: Three things, and the first two are cheap only if the third is also true. The **name table**: `set_cc_algorithm_name("bbr2")` returns `Ok(())`, and `"reno"`, `"cubic"` and `"bbr"` still do. `"BBR2"`, `"bbr2 "`, `"bbr3"` and `""` all return `Err(quiche::Error::CongestionControl)`, so the accept list grew by exactly one entry and did not become permissive. The **discriminant**: `(Reno as u8, CUBIC as u8, BBR as u8, BBR2 as u8)` is `(0, 1, 2, 3)`, asserted as a tuple in one assertion so the message carries all four. BBR2 has to be appended after BBR rather than inserted among the existing three, because the values cross the C boundary and step 01's and step 02's C groups pin the earlier ones. The **behaviour**: a `pair::Pair` built with `set_cc_algorithm(CongestionControlAlgorithm::BBR2)` on both sides handshakes, carries a 256 KiB body to completion byte-for-byte, and ends with a congestion window no smaller than the one it started the transfer with (the assertion is `>=`, not `>`) and `Stats::sent_bytes` at least the length of the body. Only ratios and inequalities are asserted, never an absolute window size or strict growth: a BBR-family controller's window is a function of its bandwidth and RTT estimates, an in-memory pair with no propagation delay reads both off the host's scheduling, and pinning a number -- or demanding the window rise -- would be pinning this machine. The same transfer is run once under `"bbr"` and once under `"bbr2"` and both must complete, so a candidate that aliases the new name onto the old algorithm still passes this group -- that is deliberate, since no observation available to a black-box grader can distinguish the two control laws on a lossless in-memory path, and asserting a difference would be asserting a machine-dependent accident.
score_if cap-bbr2 run_case cap-bbr2 cap cap_bbr2
# T1/T4: A C program the grader writes is compiled against `/app/quiche/include/quiche.h`, linked against the `libquiche.a` produced by `cargo build --features ffi`, and run. The grader builds the candidate's library itself with that feature into a scratch target directory, so a candidate whose default build omits the FFI is not penalised; a candidate whose `ffi` feature does not exist, or does not produce a `staticlib`, is. The link line is `-lpthread -ldl -lm -lstdc++` and nothing else, so the archive has to be self-contained exactly as step 01's group required. The program then drives the new path and connection-ID surface and prints a `key=value` report the grader parses: * `quiche_connect`, then `quiche_conn_send` to pull the Initial out, so there is a real connection to ask questions of. * `quiche_conn_scids_left` and `quiche_conn_active_scids` before and after a `quiche_conn_new_scid` call, with the sequence number the call writes through its out-parameter. The first issued ID is sequence 1 and `active_scids` rises by one, which is the C mirror of the step 08 Rust group. * `quiche_conn_source_ids` walked with `quiche_connection_id_iter_next` until it returns `false`, reporting how many IDs it yielded and the length of the first one; then `quiche_connection_id_iter_free`. The iterator has to be a real iterator over the connection's state, not a snapshot of one element. * `quiche_conn_peer_transport_params` returning **`false`** on a client that has not yet processed the server's flight -- the C mirror of `None`, and the observable half of the `Stats` split. A candidate that returns `true` with a zeroed struct fails. On a handshaken server it returns `true`, and the program then reads the ten leading `uint64_t` members of `quiche_transport_params` back and compares them against the seven distinctive numbers the peer's `quiche_config_*` calls set plus the three RFC 9000 Section 18.2 defaults the peer left alone. **Only those ten are read.** The Rust mirror of this struct carries no `#[repr(C)]` at this release, so the compiler is free to reorder the `bool` and the three members behind it and the C side reads garbage there; the ten leading `uint64_t`s line up under the reference layout and would still line up if the attribute were added, so they are the part of the struct a candidate can be held to. * `quiche_conn_probe_path` on a connection with no spare connection IDs returning the C value of `Error::OutOfIdentifiers` (-18), and, once IDs have been issued, returning 0 and driving `quiche_conn_is_path_validated` for that 4-tuple from 0 to 1. `quiche_conn_is_path_validated` on a 4-tuple that is not a path of the connection returns `QUICHE_ERR_INVALID_STATE` (-6) rather than crashing or reporting a plain `false`: the C function returns `v as c_int` on success and the error code otherwise, so -6 is distinguishable from 0. * `quiche_conn_retired_scids` reading zero on a fresh connection, rising to 1 after `quiche_conn_retire_dcid` retires a peer ID, and `quiche_conn_retire_dcid` on a sequence number that was never issued failing with a code that says why: `QUICHE_ERR_OUT_OF_IDENTIFIERS` (-18) on a client holding a single destination ID and no spare to replace it with, because the spare is checked before the sequence number is looked up, and `QUICHE_ERR_INVALID_STATE` (-6) once a spare exists and the sequence number itself is the problem. The same program then drives a real in-memory HTTP/3 exchange over the FFI -- `quiche_h3_send_request`, `quiche_h3_send_priority_update_for_request`, `quiche_h3_send_goaway` and a `quiche_conn_stream_shutdown` with error 0x100 -- and asks `quiche_h3_event_type` for the integer behind each event `quiche_h3_conn_poll` hands back. HEADERS, GOAWAY, RESET and PRIORITY_UPDATE must report 0, 3, 4 and 5, the values the header's `enum quiche_h3_event_type` declares. At the previous milestone the implementation returned 4, 5 and 6 for the last three while the header declared 3, 4 and 5, so every C caller that switched on the enum took the wrong branch; this half of the group fails on step 09's tree without reading a line of anyone's source. On step 09's tree it does not even link: ten of the functions the program calls are not in that release's header. Nothing here greps the header or the Rust source. Every value comes from a compiled, linked, executed C program, and a declaration that disagrees with the Rust behind it produces either a link error or a wrong number.
score_if cap-ffi-paths run_case cap-ffi-paths cap cap_ffi_paths
# T4: The `MtuUpdated` event as the candidate's own `qlog` crate serialises it. The grader writes a small Rust program depending on `/app/qlog` by path, builds it against the candidate's workspace, and runs it; the program constructs a `QlogStreamer` over a file in a scratch directory with `log_level: EventImportance::Extra`, calls `start_log()`, emits two `MtuUpdated` events and one event of a kind step 06 already pinned, then `finish_log()`. The grader reads the file back and parses it as a JSON Text Sequence, and requires: * the first record is the JSON-SEQ header step 06 specified -- `qlog_version` `"0.3"`, `qlog_format` `"JSON-SEQ"`, no `traces` key -- so the new event did not arrive by changing the envelope; * both `MtuUpdated` records have `name` exactly `"connectivity:mtu_updated"`, and each record's key set is exactly `{data, name, time}`; * the event emitted with only `new` set has a `data` object whose key set is exactly `{new}` -- `old` and `done` are omitted, not serialised as `null`, which is what `skip_serializing_none` on the struct means; * the event emitted with all three set has `data` keys exactly `{old, new, done}` with the numbers and the boolean the program passed in, round-tripped as JSON numbers rather than strings; * a second streamer, built at `EventImportance::Core` over a second file and fed the same `MtuUpdated`, writes **no** event record for it, because the event's importance is `Extra`. The program reports the `Err(Error::Done)` it gets back, and the second file holds its header record and the one `Core` control event and nothing else. This is what separates an implementation that added the schema type from one that also registered its importance -- and the control event is what separates it from a streamer that silently drops everything. No time value and no `reference_time` is asserted anywhere, and no substring search is used: every check is against parsed JSON key sets and values.
score_if cap-mtu-updated-qlog run_case cap-mtu-updated-qlog cap cap_mtu_updated_qlog
# T3: `Connection::peer_transport_params()` and the disappearance of the `peer_*` fields from `Stats`, on a `pair::Pair` whose two `Config`s are given deliberately distinctive, mutually different values -- `set_initial_max_data`, `set_initial_max_streams_bidi`, `set_max_idle_timeout`, `set_max_recv_udp_payload_size`, `set_active_connection_id_limit` and `set_disable_active_migration`, every one of them a number (or a boolean) that differs between the client and the server and appears nowhere else in the harness. The particular numbers are a choice of this group's, not a protocol fact, and they are deliberately **not** written down here. Their whole job is to be values no candidate could produce except by carrying the peer's parameters across the handshake and reading them back out; a contract that named them would turn the assertion into something a lookup table could satisfy. What the contract pins is the shape -- every value distinct, every value different on the two ends, none of them a default -- and the accessor's obligation to report the *peer's* number for each one. Before any packet is exchanged, `peer_transport_params()` is `None` on both peers. That is the assertion the old `Stats` mirror could not express, and a candidate that returns `Some(TransportParams::default())` from the start fails here rather than anywhere else. After the handshake, each peer reads back **the other's** configured values, not its own: the client's view of `initial_max_data` is what the server was given, and the asymmetry is what catches an implementation that wired the accessor to the local parameters. `max_idle_timeout` is in milliseconds, matching the setter. `disable_active_migration` crosses as a boolean in both directions independently. `max_udp_payload_size` and `active_conn_id_limit` are asserted separately from the rest, because a struct that carried *some* of the peer's answers and its own configuration for the remainder would satisfy one block and not the other. The two parameters no `Config` in this group touches -- `ack_delay_exponent` and `max_ack_delay` -- read as RFC 9000 Section 18.2's defaults, 3 and 25, on both ends. A peer that accepts a default does not send the parameter at all, so an implementation that fills the struct only from what appeared on the wire reports zero here and fails. `initial_source_connection_id` is `Some` and equals the connection ID the peer actually used, which is the one field that ties the struct to this connection rather than to a config; `retry_source_connection_id` and `max_datagram_frame_size` are `None`, because no Retry was issued and neither side enabled DATAGRAM. The group also requires that the `Stats` struct returned by `stats()` has the `peer_*` fields **gone**: it reads every one of the fourteen fields `Stats` is specified to have, in one destructuring-style assertion, so a `Stats` that still carries the thirteen mirrors alongside the new counters does not compile against this group and a `Stats` missing any of the fourteen does not either.
score_if cap-peer-transport-params run_case cap-peer-transport-params cap cap_peer_transport_params
# T3: The four renamed methods, driven through the same sequence step 08 and step 09 drove the old names through, so the group is a rename check with real behaviour underneath it rather than a symbol-existence check. A `pair::Pair` handshakes with `set_active_connection_id_limit(3)`. Then: `scids_left()` is positive and `active_scids()` is 1 on each peer; `new_scid(&fresh_id, token, false)` returns `Ok(1)` on the client, because sequence 0 came from the handshake; `active_scids()` rises to 2 and `scids_left()` falls by one, so the two accessors are views of one piece of state and not independent counters; driving the pair makes the server's `available_dcids()` rise, which is the observable consequence of the NEW_CONNECTION_ID frame arriving; issuing past the peer's limit with `retire_if_needed = false` returns `Err(quiche::Error::IdLimit)`; and `retire_dcid(0)` on the server, driven until the retirement reaches the client, raises the client's `retired_scids()` to 1 and shrinks its `source_ids()` back to one entry. `source_ids()` and `retired_scids()` are read throughout under their step 09 names, which is the half of the assertion that pins the rename as *exactly four methods*: a candidate that renamed everything containing "source" to "scid" breaks `source_ids()` and fails here, and a candidate that renamed nothing fails to compile against the group at all.
score_if cap-scid-renames run_case cap-scid-renames cap cap_scid_renames
# T3: The four new `Stats` counters, and specifically the asymmetry RFC 9000 Section 3.5 creates between the two endpoints of one connection. A `pair::Pair` handshakes and the client writes one byte to each of streams 0, 2, 4 and 8. All four counters read zero on both peers at that point. **Reset path.** The client calls `stream_shutdown(0, Shutdown::Write, 1001)` and the pair is driven until quiet. The client now reads `reset_stream_count_local` 1 and `reset_stream_count_remote` 0, while the server reads local 0 and remote 1: the same RESET_STREAM frame is counted under a different name at each end, which is the whole point of the local/remote split. The server then resets stream 0 in reaction and both peers read 1/1. The client resets streams 2, 4 and 8; the server resets 4 and 8; and the final reading is client local 4 / remote 3 and server local 3 / remote 4 -- the two endpoints disagree, by exactly the number of resets each originated. Every reading is taken after the pair has been driven, because the counters move when a frame is sent or received, not when the API call returns. **Stop path**, on a fresh pair. The server calls `stream_shutdown(0, Shutdown::Read, 1001)`, which sends STOP_SENDING. After driving, the server reads `stopped_stream_count_local` 1 and `reset_stream_count_remote` 1, and the client reads `stopped_stream_count_remote` 1 and `reset_stream_count_local` 1: the client auto-reset the stream because Section 3.5 requires it, so one API call moved a counter on each side of each name. Repeating for four streams gives server 4/0/0/4 and client 0/4/4/0 across (stopped_local, stopped_remote, reset_local, reset_remote). An implementation that counts API calls rather than frames, or that counts both directions into one field, cannot produce that table.
score_if cap-stream-reset-stop-counts run_case cap-stream-reset-stop-counts cap cap_stream_reset_stop_counts
# T3: `Stats::path_challenge_rx_count` and the bound `Config::set_path_challenge_recv_max_queue_len` puts on responding. On a pair with `set_active_connection_id_limit(4)` and connection IDs exchanged, the server's `path_challenge_rx_count` is zero after the handshake and after the client has sent STREAM frames on the active path: ordinary data does not move it. The client then probes a second local address; the server's count reaches 1 and rises by exactly one per probe, so the counter is of PATH_CHALLENGE frames and not of packets or of paths. The count moves **before** the queue decides anything. With `set_path_challenge_recv_max_queue_len(1)` on the server and the same 4-tuple re-probed three further times, each datagram delivered before the server is ever given a chance to answer, four challenges reach a path whose queue holds one -- and the count rises by all four. A counter incremented where the frame is queued would stop at one. That is the assertion that distinguishes a counter incremented on receipt from one incremented at the point of queueing. What the group deliberately does **not** assert is a *behavioural* consequence of the bound. Measured against the reference: with the bound at one and four challenges outstanding, the path still validates, because the one challenge that was queued still produces a PATH_RESPONSE and one response is all validation needs. The discard is genuinely invisible from outside the connection; only the counter's disagreement with it is visible. The group asserts the path *does* validate, so that a candidate who made the discard observable by dropping validation would be caught too. `send_on_path` for a 4-tuple that is not a path of this connection returns `Err(quiche::Error::InvalidState)` -- checked on a foreign local address and on a foreign peer address separately, because the check is on the 4-tuple and not on either half -- and `send_on_path` on the active path with nothing pending returns `Err(quiche::Error::Done)` rather than an empty packet. Both are inherited from step 08 and re-read here because the queue bound must not have changed them.
score_if cap-path-challenge-queue run_case cap-path-challenge-queue cap cap_path_challenge_queue

# ---------------------------------------------------------------------------
# 7. Report.
#
#     reward = gate x score
#
# `score.py` does the arithmetic against the manifest, because the two checks
# that matter are both about groups going missing -- a declared group with no
# recorded result, or a recorded result for a group nobody priced -- and both
# are easier to get right over parsed JSON than over shell word splitting. It
# prints the reward and writes reward_details.json, naming the gate group that
# vetoed the step and quoting what it saw.
#
# If it cannot run at all, that is a verifier defect and not a capability
# result, and the crash path in section 0 says so in those words.
# ---------------------------------------------------------------------------
score_input=$(printf '{"step_num":%d,"tag":"%s","log_dir":"%s","manifest":"/tests/groups.json","crate_dir":"%s","candidate_build":%s,"harness_build":%s,"fixture_ok":%s,"budget_exhausted":%s}\n' \
    "$step_num" "$step_tag" "$log_dir" "$crate_dir" \
    "$([ "$candidate_build" -eq 1 ] && echo true || echo false)" \
    "$([ "$harness_build" -eq 1 ] && echo true || echo false)" \
    "$([ "$fixture_ok" -eq 1 ] && echo true || echo false)" \
    "$([ "$budget_exhausted" -eq 1 ] && echo true || echo false)")

reward=$(printf '%s' "$score_input" | python3 /tests/score.py 2>"$log_dir/score.err")
score_status=$?

case "$reward" in
    0|0.*|1|1.0*) ;;
    *) reward='' ;;
esac

if [ "$score_status" -ne 0 ] || [ -z "$reward" ]; then
    fail_everything "the verifier could not score this step: score.py exited $score_status saying '$(tr -d '\n"\\' < "$log_dir/score.err" | tail -c 300)'. Nothing was measured, so this is an unattributable verifier failure rather than a capability result"
    reported=1
    exit 0
fi

reported=1
report "$reward"
exit 0
